// Hand-modelled Pakistan landmarks: Blender models exported as Draco GLBs, loaded lazily by distance.
// The list comes from manifest_data.js, generated by build/pk/blender/gen_index.py from manifest/*.json.
//
// The contract with main.js is the same as landmarks_sh.js (id, name, lat, lon, headingDeg, height, suppress, build):
//   build() returns a Group at once; the engine places it on terrain (origin at lat/lon, rotation.y = -headingDeg),
//   flattens the ground under suppress, hides OSM buildings there, and lerps userData.nightMats every frame.
// This module fills the Group asynchronously: the far LOD first, then the full model when the camera comes close.
// Model space is metres, Y up, the building front on -Z (see build/pk/blender/pkkit.py).
import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { DRACOLoader } from "three/addons/loaders/DRACOLoader.js";
import { LANDMARK_MANIFEST } from "./manifest_data.js";

const here = new URL("./", import.meta.url).href;
const draco = new DRACOLoader().setDecoderPath(new URL("../../vendor/three/examples/jsm/libs/draco/gltf/", import.meta.url).href);
draco.setDecoderConfig({ type: "wasm" });
draco.setWorkerLimit(2);
const loader = new GLTFLoader().setDRACOLoader(draco);

// how close the camera must be for the full model, by size class (metres), with a wider band for keeping it
const FULL_IN = { hero: 2600, normal: 1500, plain: 900 };
const FULL_OUT = 1.3;
const MIN_GAP_MS = 240;           // at most about four models start loading a second
const TICK_MS = 320;

// Per-landmark placement that the manifests do not carry (a re-export rewrites them, so it lives here).
//   baseOffset: metres added to the DEM height at the anchor, for the model and the ground flattened under it
//   padRing:    [[lat, lon], ...] flattened instead of the suppress ring
//   distPts:    [[lat, lon], ...] the full model is chosen by the nearest of these, for models that run far from their anchor
const SITE = {
  // the DEM reads 600.8 m at the anchor but the roads east and south-east of the platform run at 591 to 593 m: this seats the base 1 to 3 m above them
  faisal_mosque: { baseOffset: -6.8 },
  // deck (model z 35) set to the game road on the crest, 526.1 to 527.3 m, and just above the game lake at 526.1 m; the ring is the outline of the model's low parts
  rawal_dam_spillway: { baseOffset: -32.02, padRing: [[33.69355, 73.122141], [33.693536, 73.122169], [33.693473, 73.122292], [33.693486, 73.122649], [33.693693, 73.123701], [33.693734, 73.123733], [33.69381, 73.123792], [33.693889, 73.123716], [33.69399, 73.123613], [33.69404, 73.12339], [33.694053, 73.123322], [33.694058, 73.123197], [33.694061, 73.123073], [33.694052, 73.122949], [33.694033, 73.122827], [33.694002, 73.122708], [33.693961, 73.122594], [33.693909, 73.122487], [33.693855, 73.122379], [33.693763, 73.122206], [33.693661, 73.122169]] },
  // the rope line from the dossier: the model runs about 3 km up the hill from its anchor
  patriata_chairlift_towers: { distPts: [[33.87418, 73.45794], [33.87345, 73.45962], [33.87218, 73.46255], [33.87144, 73.46421], [33.87031, 73.46673], [33.86905, 73.4696], [33.86752, 73.4715], [33.86289, 73.47652], [33.86075, 73.47884], [33.85998, 73.47966], [33.85722, 73.48265]] },
};
const M_LAT = 110950, mLon = lat => 111320 * Math.cos(lat * Math.PI / 180);

// the camera's distance to a landmark: to its anchor, or to the nearest of its distPts
function siteDist(R, cam) {
  const P = R.group.position, D = R.def;
  let d = Math.hypot(cam.x - P.x, cam.z - P.z);
  if (D.distPts) for (const [la, lo] of D.distPts) d = Math.min(d, Math.hypot(cam.x - (P.x + (lo - D.lon) * mLon(D.lat)), cam.z - (P.z - (la - D.lat) * M_LAT)));
  return d;
}

// Draco already decodes on workers. What stalled the main thread was the first draw uploading every buffer of a model in one frame.
// Each texture and mesh goes up alone, one per frame, into a 1 by 1 target, before the model is shown.
const upScene = new THREE.Scene(), upCam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1), upMat = new THREE.MeshBasicMaterial();
let upTarget = null;
const nextFrame = () => new Promise(r => requestAnimationFrame(r));
async function upload(root, R, token) {
  const G = window.GAME, r = G && G.renderer;
  if (!r) return;
  if (!upTarget) upTarget = new THREE.WebGLRenderTarget(1, 1, { depthBuffer: false });
  const textures = new Set(), meshes = [];
  root.traverse(o => {
    if (!o.isMesh) return;
    meshes.push(o);
    for (const m of Array.isArray(o.material) ? o.material : [o.material]) for (const k of Object.keys(m)) { const v = m[k]; if (v && v.isTexture) textures.add(v); }
  });
  for (const t of textures) {
    await nextFrame();
    if (R.token !== token) return;
    r.initTexture(t);
  }
  for (const m of meshes) {
    await nextFrame();
    if (R.token !== token) return;
    const proxy = new THREE.Mesh(m.geometry, upMat), prev = r.getRenderTarget();
    proxy.frustumCulled = false;
    upScene.add(proxy);
    r.setRenderTarget(upTarget);
    try { r.render(upScene, upCam); } finally { r.setRenderTarget(prev); upScene.remove(proxy); }
  }
}

const active = new Set();         // runtime entries of the landmarks the engine currently has in the world
let loading = 0, lastStart = 0, timer = 0;

function camPos() {
  const c = window.GAME && window.GAME.camera;
  return c ? c.position : null;
}

function tick() {
  timer = active.size ? setTimeout(tick, TICK_MS) : 0;
  const cam = camPos();
  const now = performance.now();
  const want = [];
  for (const R of active) {
    if (!R.group) continue;
    const d = cam ? siteDist(R, cam) : 1e9;
    R.dist = d;
    const fullIn = FULL_IN[R.def.budget] || FULL_IN.normal;
    if (d > fullIn * FULL_OUT && R.full) unloadFull(R);
    else if (!R.full && !R.fullBusy && d < fullIn) want.push({ R, full: true, d });
    if (!R.far && !R.farBusy) want.push({ R, full: false, d: d + 200 });
  }
  if (want.length && loading < 2 && now - lastStart >= MIN_GAP_MS) {
    want.sort((a, b) => a.d - b.d);
    const job = want[0];
    lastStart = now;
    start(job.R, job.full);
  }
}

function adopt(root, R) {
  // shadows on, material tweaks, and move the night glow of every material into the engine's day/night list
  const seen = new Set();
  root.traverse(o => {
    if (!o.isMesh) return;
    o.castShadow = true; o.receiveShadow = true; o.frustumCulled = true;
    const list = Array.isArray(o.material) ? o.material : [o.material];
    for (const m of list) {
      if (seen.has(m)) continue;
      seen.add(m);
      if (m.emissive && (m.emissive.r + m.emissive.g + m.emissive.b) > 0.0001) {
        const night = m.emissiveIntensity;
        m.emissiveIntensity = 0;
        R.group.userData.nightMats.push({ mat: m, day: 0, night });
      }
    }
  });
}

function compile(root) {
  const G = window.GAME;
  if (!G || !G.renderer || !G.renderer.compileAsync || !G.fx || !G.fx.composer) return Promise.resolve();
  const r = G.renderer, prev = r.getRenderTarget();
  r.setRenderTarget(G.fx.composer.readBuffer);
  try { return r.compileAsync(root, G.camera, G.scene).catch(() => {}); } finally { r.setRenderTarget(prev); }
}

function start(R, full) {
  const token = R.token;
  if (full) R.fullBusy = true; else R.farBusy = true;
  loading++;
  const url = here + (full ? R.def.glb : R.def.glbFar);
  loader.loadAsync(url).then(async (gltf) => {
    const root = gltf.scene;
    root.name = R.def.id + (full ? ":full" : ":far");
    if (R.token !== token) { disposeTree(root); return; }
    adopt(root, R);
    await compile(root);
    if (R.token !== token) { disposeTree(root); return; }
    await upload(root, R, token);
    if (R.token !== token) { disposeTree(root); return; }
    if (full) {
      R.full = root;
      R.group.add(root);
      if (R.far) R.far.visible = false;
    } else {
      R.far = root;
      R.group.add(root);
      if (R.full) R.far.visible = false;
    }
  }).catch(e => console.warn("landmarks_pk", R.def.id, full ? "full" : "far", e && e.message)).finally(() => {
    loading--;
    if (full) R.fullBusy = false; else R.farBusy = false;
  });
}

function unloadFull(R) {
  const m = R.full;
  R.full = null;
  if (R.far) R.far.visible = true;
  R.group.remove(m);
  removeNight(R, m);
  disposeTree(m);
}

function removeNight(R, root) {
  const mats = new Set();
  root.traverse(o => { if (o.isMesh) (Array.isArray(o.material) ? o.material : [o.material]).forEach(x => mats.add(x)); });
  const list = R.group.userData.nightMats;
  for (let i = list.length - 1; i >= 0; i--) if (mats.has(list[i].mat)) list.splice(i, 1);
}

function disposeTree(root) {
  root.traverse(o => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) (Array.isArray(o.material) ? o.material : [o.material]).forEach(m => {
      for (const k of Object.keys(m)) { const v = m[k]; if (v && v.isTexture) v.dispose(); }
      m.dispose();
    });
  });
}

function makeDef(M) {
  const def = {
    id: M.id, name: M.name, lat: M.lat, lon: M.lon, headingDeg: M.headingDeg, height: M.height,
    suppress: M.suppress, budget: M.budget, glb: M.glb, glbFar: M.glbFar, ...(SITE[M.id] || {}),
    build() {
      const group = new THREE.Group();
      group.name = "lm:" + M.id;
      group.userData.nightMats = [];
      // one small mesh with the same kind of material the GLBs use, so the engine compiles that program up front
      const warm = new THREE.Mesh(warmGeo, warmMat);
      warm.frustumCulled = false;
      group.add(warm);
      const R = { def, group, far: null, full: null, farBusy: false, fullBusy: false, token: 0, dist: 1e9 };
      group.userData._pk = R;
      active.add(R);
      if (!timer) timer = setTimeout(tick, 60);
      return group;
    },
    dispose(group) {
      const R = group.userData._pk;
      if (R) { R.token++; active.delete(R); }
      group.traverse(o => { if (o.isMesh && o.geometry !== warmGeo) { if (o.geometry) o.geometry.dispose(); if (o.material && o.material !== warmMat) (Array.isArray(o.material) ? o.material : [o.material]).forEach(m => { for (const k of Object.keys(m)) { const v = m[k]; if (v && v.isTexture) v.dispose(); } m.dispose(); }); } });
    },
  };
  return def;
}

const warmGeo = new THREE.BufferGeometry();
warmGeo.setAttribute("position", new THREE.BufferAttribute(new Float32Array(9), 3));
warmGeo.setAttribute("normal", new THREE.BufferAttribute(new Float32Array(9), 3));
warmGeo.setIndex(new THREE.BufferAttribute(new Uint16Array([0, 1, 2]), 1));
const warmMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.8, metalness: 0.0, emissive: 0xffffff, emissiveIntensity: 0 });

export const LANDMARKS_PK = LANDMARK_MANIFEST.map(makeDef);
